"""Typed values for validation-only operational permit imports."""

from dataclasses import dataclass
from datetime import date
from typing import Annotated, ClassVar, Final, NewType

from pydantic import BaseModel, ConfigDict, Field

from scripts.seed_builder.models import PermitStatus, PermitType

SiteCode = NewType("SiteCode", str)
SIGNED_INT32_MIN: Final = -2147483648
SIGNED_INT32_MAX: Final = 2147483647
Quantity = Annotated[int, Field(ge=SIGNED_INT32_MIN, le=SIGNED_INT32_MAX)]


class PermitUpdate(BaseModel):
    """One fully parsed operational permit update ready for a later transaction."""

    model_config: ClassVar[ConfigDict] = ConfigDict(frozen=True)

    site_code: SiteCode
    permit_type: PermitType
    applicable: bool
    grade: str | None
    detail: str | None
    items: tuple[str, ...]
    quantity: Quantity | None
    permit_no: str | None
    authority: str | None
    issued_on: date | None
    conditions: str | None
    status: PermitStatus


@dataclass(frozen=True, slots=True)
class ImportIssue:
    """One Korean operator-facing CSV validation issue."""

    file: str
    row: int
    field: str
    value: str | None
    reason: str


@dataclass(frozen=True, slots=True)
class ImportPlan:
    """A read-only validation result with no database or file side effects."""

    updates: tuple[PermitUpdate, ...]
    issues: tuple[ImportIssue, ...]


@dataclass(frozen=True, slots=True)
class PermitImportSnapshot:
    """Immutable source bytes paired with the plan parsed from those exact bytes."""

    source_name: str
    source_bytes: bytes
    plan: ImportPlan
"""Pure CSV contract validation for operational permit updates."""

import csv
import io
import re
from dataclasses import dataclass
from datetime import date
from pathlib import Path
from typing import Final

from scripts.seed_builder.models import PermitStatus, PermitType

from .models import (
    SIGNED_INT32_MAX,
    SIGNED_INT32_MIN,
    ImportIssue,
    ImportPlan,
    PermitImportSnapshot,
    PermitUpdate,
    SiteCode,
)

REQUIRED_HEADERS: Final[tuple[str, ...]] = (
    "site_code",
    "permit_type",
    "applicable",
    "grade",
    "detail",
    "items",
    "quantity",
    "permit_no",
    "authority",
    "issued_on",
    "conditions",
    "status",
)
_REQUIRED_FIELDS: Final[tuple[str, ...]] = ("site_code", "permit_type", "applicable", "status")
_KOREAN_FIELDS: Final[dict[str, str]] = {
    "site_code": "사업장 코드",
    "permit_type": "인허가 유형",
    "applicable": "적용 여부",
    "grade": "종별",
    "detail": "상세 내용",
    "items": "대상 항목",
    "quantity": "수량",
    "permit_no": "허가번호",
    "authority": "허가 기관",
    "issued_on": "발급일",
    "conditions": "허가조건",
    "status": "상태",
}


@dataclass(frozen=True, slots=True)
class _RowResult:
    """A parsed row or every issue found while parsing it."""

    update: PermitUpdate | None
    issues: tuple[ImportIssue, ...]


def _issue(file: str, row: int, field: str, value: str | None, reason: str) -> ImportIssue:
    """Build a consistently labelled operator-facing issue."""
    return ImportIssue(file, row, _KOREAN_FIELDS[field], value, reason)


def _normalized(values: dict[str, str | None]) -> dict[str, str | None]:
    """Trim CSV text and turn optional blank cells into absent values."""
    return {field: None if value is None or not value.strip() else value.strip() for field, value in values.items()}


def _required_issues(file: str, row: int, raw: dict[str, str | None]) -> tuple[ImportIssue, ...]:
    """Keep empty and whitespace-only required values distinct for operators."""
    issues: list[ImportIssue] = []
    for field in _REQUIRED_FIELDS:
        value = raw[field]
        if value is None:
            issues.append(_issue(file, row, field, value, "필수 열 값이 없습니다."))
        elif value == "":
            issues.append(_issue(file, row, field, value, "필수값이 비어 있습니다."))
        elif not value.strip():
            issues.append(_issue(file, row, field, value, "필수값에 공백만 입력되었습니다."))
    return tuple(issues)


def _parse_date(file: str, row: int, value: str | None) -> tuple[date | None, ImportIssue | None]:
    """Accept only calendar dates written exactly as YYYY-MM-DD."""
    if value is None:
        return None, None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value) is None:
        return None, _issue(file, row, "issued_on", value, "YYYY-MM-DD 형식의 유효한 날짜가 아닙니다.")
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        return None, _issue(file, row, "issued_on", value, "YYYY-MM-DD 형식의 유효한 날짜가 아닙니다.")
    return parsed, None


def _parse_boolean(file: str, row: int, value: str | None) -> tuple[bool | None, ImportIssue | None]:
    """Parse the documented true/false flag without database access."""
    if value is None:
        return None, None
    if value == "true":
        return True, None
    if value == "false":
        return False, None
    return None, _issue(file, row, "applicable", value, "true 또는 false로 입력해야 합니다.")


def _parse_quantity(file: str, row: int, value: str | None) -> tuple[int | None, ImportIssue | None]:
    """Parse optional integer quantity while keeping malformed input visible."""
    if value is None:
        return None, None
    try:
        quantity = int(value)
    except ValueError:
        return None, _issue(file, row, "quantity", value, "정수로 입력해야 합니다.")
    if quantity < SIGNED_INT32_MIN or quantity > SIGNED_INT32_MAX:
        return None, _issue(file, row, "quantity", value, "부호 있는 32비트 정수 범위여야 합니다.")
    return quantity, None


def _parse_row(file: str, row: int, raw: dict[str, str | None], known_sites: frozenset[SiteCode]) -> _RowResult:
    """Parse one CSV row after reporting every independent operator action."""
    issues = list(_required_issues(file, row, raw))
    values = _normalized(raw)
    site_code = values["site_code"]
    permit_type_value = values["permit_type"]
    status_value = values["status"]
    applicable, applicable_issue = _parse_boolean(file, row, values["applicable"])
    issued_on, date_issue = _parse_date(file, row, values["issued_on"])
    quantity, quantity_issue = _parse_quantity(file, row, values["quantity"])
    for issue in (applicable_issue, date_issue, quantity_issue):
        if issue is not None:
            issues.append(issue)

    parsed_site = SiteCode(site_code) if site_code is not None else None
    if parsed_site is not None and parsed_site not in known_sites:
        issues.append(_issue(file, row, "site_code", site_code, "등록되지 않은 사업장 코드입니다."))

    permit_type: PermitType | None = None
    if permit_type_value is not None:
        try:
            permit_type = PermitType(permit_type_value)
        except ValueError:
            issues.append(_issue(file, row, "permit_type", permit_type_value, "허용되지 않는 인허가 유형입니다."))

    status: PermitStatus | None = None
    if status_value is not None:
        try:
            status = PermitStatus(status_value)
        except ValueError:
            issues.append(_issue(file, row, "status", status_value, "허용되지 않는 상태값입니다."))

    if issues or parsed_site is None or permit_type is None or applicable is None or status is None:
        return _RowResult(None, tuple(issues))
    return _RowResult(
        PermitUpdate(
            site_code=parsed_site,
            permit_type=permit_type,
            applicable=applicable,
            grade=values["grade"],
            detail=values["detail"],
            items=tuple(item.strip() for item in (values["items"] or "").split("|") if item.strip()),
            quantity=quantity,
            permit_no=values["permit_no"],
            authority=values["authority"],
            issued_on=issued_on,
            conditions=values["conditions"],
            status=status,
        ),
        (),
    )


def _business_key(raw: dict[str, str | None]) -> tuple[str, str] | None:
    values = _normalized(raw)
    site_code = values["site_code"]
    permit_type = values["permit_type"]
    if site_code is None or permit_type is None:
        return None
    return site_code, permit_type


def validate_permit_updates_bytes(
    source_name: str,
    source_bytes: bytes,
    known_sites: frozenset[SiteCode],
) -> ImportPlan:
    """Validate one immutable CSV byte snapshot without database or file writes."""
    try:
        text = source_bytes.decode("utf-8-sig")
        reader = csv.DictReader(io.StringIO(text, newline=""), strict=True)
        headers = tuple(reader.fieldnames or ())
        if headers != REQUIRED_HEADERS:
            return ImportPlan(
                (),
                (
                    ImportIssue(
                        source_name,
                        0,
                        "헤더",
                        ",".join(headers),
                        "템플릿과 정확히 일치하는 헤더가 필요합니다.",
                    ),
                ),
            )
        rows = tuple(enumerate(reader, start=1))
    except (UnicodeDecodeError, csv.Error):
        return ImportPlan((), (ImportIssue(source_name, 0, "CSV", None, "CSV 형식이 올바르지 않습니다."),))

    updates: list[PermitUpdate] = []
    issues: list[ImportIssue] = []
    seen: set[tuple[str, str]] = set()
    for row, values in rows:
        raw = {header: values[header] for header in REQUIRED_HEADERS}
        key = _business_key(raw)
        if key is not None:
            if key in seen:
                issues.append(
                    ImportIssue(
                        source_name,
                        row,
                        "사업장 코드, 인허가 유형",
                        ",".join(key),
                        "파일 안에서 중복된 인허가 업무 키입니다.",
                    )
                )
            seen.add(key)
        extra_cells = values.get(None)
        if extra_cells is not None:
            issues.append(
                ImportIssue(
                    source_name,
                    row,
                    "추가 열",
                    ",".join(extra_cells),
                    "헤더보다 많은 값이 입력되었습니다.",
                )
            )
        result = _parse_row(source_name, row, raw, known_sites)
        issues.extend(result.issues)
        if result.update is None:
            continue
        updates.append(result.update)
    if issues:
        return ImportPlan((), tuple(issues))
    return ImportPlan(tuple(updates), ())


def read_permit_import_snapshot(path: Path, known_sites: frozenset[SiteCode]) -> PermitImportSnapshot:
    """Read once and bind validation results to the same immutable bytes."""
    try:
        source_bytes = path.read_bytes()
    except FileNotFoundError:
        plan = ImportPlan((), (ImportIssue(path.name, 0, "파일", None, "파일을 찾을 수 없습니다."),))
        return PermitImportSnapshot(path.name, b"", plan)
    plan = validate_permit_updates_bytes(path.name, source_bytes, known_sites)
    return PermitImportSnapshot(path.name, source_bytes, plan)


def validate_permit_updates(path: Path, known_sites: frozenset[SiteCode]) -> ImportPlan:
    """Preserve the public path API by delegating to one immutable byte snapshot."""
    return read_permit_import_snapshot(path, known_sites).plan
"""Command boundary for validated private permit update files."""

import csv
import os
import sys
from collections.abc import Sequence
from pathlib import Path
from typing import Final

from .models import ImportPlan, SiteCode
from .transaction import ImportClient, ImportClientError, build_envelope, load_config
from .validate import read_permit_import_snapshot, validate_permit_updates

_COMMAND_ARGUMENT_COUNT: Final = 2
_DRY_RUN_ARGUMENT_COUNT: Final = 3


def _known_sites() -> frozenset[SiteCode]:
    """Read the versioned site master without connecting to Supabase."""
    site_master = Path(__file__).resolve().parents[2] / "seed" / "sites.csv"
    with site_master.open(encoding="utf-8-sig", newline="") as handle:
        return frozenset(SiteCode(row["code"].strip()) for row in csv.DictReader(handle) if row["code"].strip())


def _print_issues(plan: ImportPlan) -> int:
    if not plan.issues:
        return 0
    print(f"검증 실패: {len(plan.issues)}건")
    for issue in plan.issues:
        print(f"{issue.file} 데이터 {issue.row}행 {issue.field}: {issue.value!r} - {issue.reason}")
    return 1


def _apply(file_name: str, *, dry_run: bool) -> int:
    path = Path(file_name)
    snapshot = read_permit_import_snapshot(path, _known_sites())
    plan = snapshot.plan
    if plan.issues:
        return _print_issues(plan)
    if not plan.updates:
        print("반영할 인허가 행이 없습니다.")
        return 1
    if dry_run:
        print(f"미리보기: 검증된 인허가 변경 {len(plan.updates)}건, 네트워크 요청 0건")
        for update in plan.updates:
            print(f"- {update.site_code} / {update.permit_type.value} / {update.status.value}")
        return 0
    try:
        batch_id = ImportClient(load_config(os.environ, Path.cwd() / ".env")).apply_envelope(
            build_envelope(snapshot)
        )
    except ImportClientError as error:
        print(f"반영 실패: {error}")
        return 1
    print(f"반영 완료: {len(plan.updates)}건, 배치 {batch_id}")
    return 0


def main(argv: Sequence[str] | None = None) -> int:
    """Validate or transactionally apply a private permit CSV."""
    arguments = tuple(sys.argv[1:] if argv is None else argv)
    if len(arguments) == _COMMAND_ARGUMENT_COUNT and arguments[0] == "validate":
        plan = validate_permit_updates(Path(arguments[1]), _known_sites())
    elif len(arguments) == _COMMAND_ARGUMENT_COUNT and arguments[0] == "apply":
        return _apply(arguments[1], dry_run=False)
    elif (
        len(arguments) == _DRY_RUN_ARGUMENT_COUNT
        and arguments[0] == "apply"
        and arguments[2] == "--dry-run"
    ):
        return _apply(arguments[1], dry_run=True)
    else:
        print("사용법: uv run python -m scripts.importer.cli <validate|apply> <CSV 경로> [--dry-run]")
        return 2
    if plan.issues:
        print(f"검증 실패: {len(plan.issues)}건")
        for issue in plan.issues:
            print(f"{issue.file} 데이터 {issue.row}행 {issue.field}: {issue.value!r} - {issue.reason}")
        return 1
    print(f"검증 완료: {len(plan.updates)}건")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"""Typed Supabase RPC boundary for transactional permit imports."""

from __future__ import annotations

import hashlib
import socket
from dataclasses import dataclass
from typing import TYPE_CHECKING, ClassVar, Final, Self, override
from urllib.parse import urlsplit
from uuid import UUID

import httpx2
from pydantic import BaseModel, ConfigDict, TypeAdapter

from . import models
from .postgrest_errors import parse_safe_postgrest_error

if TYPE_CHECKING:
    from collections.abc import Mapping
    from pathlib import Path

_LIMITS: Final = httpx2.Limits(
    max_connections=200,
    max_keepalive_connections=40,
    keepalive_expiry=30.0,
)
_TIMEOUT: Final = httpx2.Timeout(connect=5.0, read=30.0, write=10.0, pool=10.0)
_SOCKET_OPTIONS: Final = [(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)]
_UUID_ADAPTER: Final = TypeAdapter(UUID)
_CONFIG_KEYS: Final = frozenset(("SUPABASE_URL", "SUPABASE_ANON_KEY", "SUPABASE_ACCESS_TOKEN"))
_MINIMUM_CREDENTIAL_LENGTH: Final = 16
_QUOTED_VALUE_MINIMUM_LENGTH: Final = 2
_ASCII_PRINTABLE_START: Final = 32
_ASCII_DELETE: Final = 127


class ImportEnvelope(BaseModel):
    """One validated file and its exact-byte idempotency identity."""

    model_config: ClassVar[ConfigDict] = ConfigDict(frozen=True)

    source_name: str
    source_sha256: str
    rows: tuple[models.PermitUpdate, ...]


@dataclass(frozen=True, slots=True)
class SupabaseConfig:
    """User-scoped credentials required by the import RPC."""

    url: str
    project_key: str
    access_token: str


@dataclass(frozen=True, slots=True)
class ImportClientError(RuntimeError):
    """A safe operator-facing RPC error that never contains credentials."""

    reason: str

    @override
    def __str__(self) -> str:
        """Return the credential-safe operator message."""
        return self.reason

    @classmethod
    def missing_config(cls) -> Self:
        """Build the error for absent user-scoped connection values."""
        return cls("SUPABASE_URL, SUPABASE_ANON_KEY, SUPABASE_ACCESS_TOKEN을 설정해야 합니다.")

    @classmethod
    def request_failed(cls) -> Self:
        """Build the redacted transport or response error."""
        return cls("Supabase 인허가 반영 요청에 실패했습니다.")

    @classmethod
    def rpc_rejected(cls, code: str, message: str) -> Self:
        """Build an allowlisted actionable server rejection."""
        return cls(f"Supabase 요청 거부 ({code}): {message}")

    @classmethod
    def config_file_failed(cls) -> Self:
        """Build the error for an unreadable local environment file."""
        return cls(".env 설정 파일을 읽을 수 없습니다.")

    @classmethod
    def invalid_config(cls) -> Self:
        """Build one redacted error for malformed URLs, credentials, or dotenv syntax."""
        return cls("Supabase 연결 설정 형식이 올바르지 않습니다.")


def build_envelope(snapshot: models.PermitImportSnapshot) -> ImportEnvelope:
    """Bind an already validated plan to the exact input bytes."""
    return ImportEnvelope(
        source_name=snapshot.source_name,
        source_sha256=hashlib.sha256(snapshot.source_bytes).hexdigest(),
        rows=snapshot.plan.updates,
    )


def _dotenv_values(dotenv_path: Path | None) -> Mapping[str, str]:
    if dotenv_path is None or not dotenv_path.is_file():
        return {}
    try:
        lines = dotenv_path.read_text(encoding="utf-8-sig").splitlines()
    except OSError as error:
        raise ImportClientError.config_file_failed() from error
    values: dict[str, str] = {}
    for raw_line in lines:
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        key, separator, raw_value = line.partition("=")
        key = key.strip()
        value = raw_value.strip()
        if not separator or key not in _CONFIG_KEYS or key in values or not value:
            raise ImportClientError.invalid_config()
        starts_quoted = value[0] in "'\""
        ends_quoted = value[-1] in "'\""
        if starts_quoted or ends_quoted:
            if (
                len(value) < _QUOTED_VALUE_MINIMUM_LENGTH
                or value[0] != value[-1]
                or value[0] not in "'\""
            ):
                raise ImportClientError.invalid_config()
            quote = value[0]
            value = value[1:-1]
            if not value or value[0:1].isspace() or value[-1:].isspace() or quote in value:
                raise ImportClientError.invalid_config()
        elif any(character.isspace() for character in value) or "#" in value:
            raise ImportClientError.invalid_config()
        values[key] = value
    return values


def _valid_url(value: str) -> bool:
    try:
        parsed = urlsplit(value)
        _ = parsed.port
    except ValueError:
        return False
    return (
        parsed.scheme in {"http", "https"}
        and parsed.hostname is not None
        and parsed.username is None
        and parsed.password is None
        and parsed.query == ""
        and parsed.fragment == ""
        and parsed.path in {"", "/"}
    )


def _valid_credential(value: str) -> bool:
    return len(value) >= _MINIMUM_CREDENTIAL_LENGTH and all(
        not character.isspace() and _ASCII_PRINTABLE_START < ord(character) < _ASCII_DELETE
        for character in value
    )


def load_config(environment: Mapping[str, str], dotenv_path: Path | None = None) -> SupabaseConfig:
    """Parse user-scoped Supabase connection settings from environment values."""
    file_values = _dotenv_values(dotenv_path)
    url = (environment.get("SUPABASE_URL") or file_values.get("SUPABASE_URL", "")).rstrip("/")
    project_key = environment.get("SUPABASE_ANON_KEY") or file_values.get("SUPABASE_ANON_KEY", "")
    access_token = environment.get("SUPABASE_ACCESS_TOKEN") or file_values.get(
        "SUPABASE_ACCESS_TOKEN", ""
    )
    if not url or not project_key or not access_token:
        raise ImportClientError.missing_config()
    if not _valid_url(url) or not _valid_credential(project_key) or not _valid_credential(access_token):
        raise ImportClientError.invalid_config()
    return SupabaseConfig(url=url, project_key=project_key, access_token=access_token)


class ImportClient:
    """Post one validated envelope through the authenticated PostgREST RPC."""

    _config: SupabaseConfig
    _transport: httpx2.BaseTransport | None

    def __init__(self, config: SupabaseConfig, transport: httpx2.BaseTransport | None = None) -> None:
        """Retain the immutable user-scoped configuration."""
        self._config = config
        self._transport = transport

    def apply_envelope(self, envelope: ImportEnvelope) -> UUID:
        """Apply the envelope once and return its durable audit batch identifier."""
        transport = self._transport or httpx2.HTTPTransport(
            http2=True, retries=0, limits=_LIMITS, socket_options=_SOCKET_OPTIONS
        )
        headers = {
            "Authorization": f"Bearer {self._config.access_token}",
            "apikey": self._config.project_key,
            "Content-Type": "application/json",
        }
        try:
            with httpx2.Client(
                transport=transport,
                timeout=_TIMEOUT,
                follow_redirects=False,
                headers=headers,
            ) as client:
                response = client.post(
                    f"{self._config.url}/rest/v1/rpc/admin_import_permit_updates",
                    json={"p_envelope": envelope.model_dump(mode="json")},
                )
                if response.is_error:
                    safe_error = parse_safe_postgrest_error(response.content)
                    if safe_error is not None:
                        raise ImportClientError.rpc_rejected(safe_error.code, safe_error.message)
                _ = response.raise_for_status()
                return _UUID_ADAPTER.validate_json(response.content)
        except ImportClientError:
            raise
        except (httpx2.HTTPError, ValueError, TypeError) as error:
            raise ImportClientError.request_failed() from error
from dataclasses import dataclass
from typing import ClassVar, Final

from pydantic import BaseModel, ConfigDict, ValidationError

_ALLOWED_CODES: Final = frozenset(("P0001", "P0002", "42501"))
_MAX_MESSAGE_LENGTH: Final = 240
_FORBIDDEN_FRAGMENTS: Final = (
    "http://",
    "https://",
    "authorization",
    "bearer ",
    "apikey",
    "access_token",
    "select ",
    "insert ",
    "update ",
    "delete ",
    "auth.",
    "public.",
    "storage.",
)


class _PostgrestError(BaseModel):
    model_config: ClassVar[ConfigDict] = ConfigDict(frozen=True, extra="forbid")

    code: str
    message: str
    details: str | None
    hint: str | None


@dataclass(frozen=True, slots=True)
class SafePostgrestError:
    """One allowlisted PostgREST rejection safe for operator output."""

    code: str
    message: str


def parse_safe_postgrest_error(content: bytes) -> SafePostgrestError | None:
    """Parse only bounded application rejections without sensitive diagnostics."""
    try:
        parsed = _PostgrestError.model_validate_json(content)
    except ValidationError:
        return None
    message = parsed.message
    normalized = message.casefold()
    is_safe = (
        parsed.code in _ALLOWED_CODES
        and bool(message)
        and len(message) <= _MAX_MESSAGE_LENGTH
        and message == message.strip()
        and all(character.isprintable() for character in message)
        and any("가" <= character <= "힣" for character in message)
        and not any(fragment in normalized for fragment in _FORBIDDEN_FRAGMENTS)
    )
    if not is_safe:
        return None
    return SafePostgrestError(code=parsed.code, message=message)

