"""Pure CSV contract validation for operational permit updates."""

import csv
import io
import re
from dataclasses import dataclass
from datetime import date
from pathlib import Path
from typing import Final

from scripts.seed_builder.models import PermitStatus, PermitType

from .models import (
    SIGNED_INT32_MAX,
    SIGNED_INT32_MIN,
    ImportIssue,
    ImportPlan,
    PermitImportSnapshot,
    PermitUpdate,
    SiteCode,
)

REQUIRED_HEADERS: Final[tuple[str, ...]] = (
    "site_code",
    "permit_type",
    "applicable",
    "grade",
    "detail",
    "items",
    "quantity",
    "permit_no",
    "authority",
    "issued_on",
    "conditions",
    "status",
)
_REQUIRED_FIELDS: Final[tuple[str, ...]] = ("site_code", "permit_type", "applicable", "status")
_KOREAN_FIELDS: Final[dict[str, str]] = {
    "site_code": "사업장 코드",
    "permit_type": "인허가 유형",
    "applicable": "적용 여부",
    "grade": "종별",
    "detail": "상세 내용",
    "items": "대상 항목",
    "quantity": "수량",
    "permit_no": "허가번호",
    "authority": "허가 기관",
    "issued_on": "발급일",
    "conditions": "허가조건",
    "status": "상태",
}


@dataclass(frozen=True, slots=True)
class _RowResult:
    """A parsed row or every issue found while parsing it."""

    update: PermitUpdate | None
    issues: tuple[ImportIssue, ...]


def _issue(file: str, row: int, field: str, value: str | None, reason: str) -> ImportIssue:
    """Build a consistently labelled operator-facing issue."""
    return ImportIssue(file, row, _KOREAN_FIELDS[field], value, reason)


def _normalized(values: dict[str, str | None]) -> dict[str, str | None]:
    """Trim CSV text and turn optional blank cells into absent values."""
    return {field: None if value is None or not value.strip() else value.strip() for field, value in values.items()}


def _required_issues(file: str, row: int, raw: dict[str, str | None]) -> tuple[ImportIssue, ...]:
    """Keep empty and whitespace-only required values distinct for operators."""
    issues: list[ImportIssue] = []
    for field in _REQUIRED_FIELDS:
        value = raw[field]
        if value is None:
            issues.append(_issue(file, row, field, value, "필수 열 값이 없습니다."))
        elif value == "":
            issues.append(_issue(file, row, field, value, "필수값이 비어 있습니다."))
        elif not value.strip():
            issues.append(_issue(file, row, field, value, "필수값에 공백만 입력되었습니다."))
    return tuple(issues)


def _parse_date(file: str, row: int, value: str | None) -> tuple[date | None, ImportIssue | None]:
    """Accept only calendar dates written exactly as YYYY-MM-DD."""
    if value is None:
        return None, None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value) is None:
        return None, _issue(file, row, "issued_on", value, "YYYY-MM-DD 형식의 유효한 날짜가 아닙니다.")
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        return None, _issue(file, row, "issued_on", value, "YYYY-MM-DD 형식의 유효한 날짜가 아닙니다.")
    return parsed, None


def _parse_boolean(file: str, row: int, value: str | None) -> tuple[bool | None, ImportIssue | None]:
    """Parse the documented true/false flag without database access."""
    if value is None:
        return None, None
    if value == "true":
        return True, None
    if value == "false":
        return False, None
    return None, _issue(file, row, "applicable", value, "true 또는 false로 입력해야 합니다.")


def _parse_quantity(file: str, row: int, value: str | None) -> tuple[int | None, ImportIssue | None]:
    """Parse optional integer quantity while keeping malformed input visible."""
    if value is None:
        return None, None
    try:
        quantity = int(value)
    except ValueError:
        return None, _issue(file, row, "quantity", value, "정수로 입력해야 합니다.")
    if quantity < SIGNED_INT32_MIN or quantity > SIGNED_INT32_MAX:
        return None, _issue(file, row, "quantity", value, "부호 있는 32비트 정수 범위여야 합니다.")
    return quantity, None


def _parse_row(file: str, row: int, raw: dict[str, str | None], known_sites: frozenset[SiteCode]) -> _RowResult:
    """Parse one CSV row after reporting every independent operator action."""
    issues = list(_required_issues(file, row, raw))
    values = _normalized(raw)
    site_code = values["site_code"]
    permit_type_value = values["permit_type"]
    status_value = values["status"]
    applicable, applicable_issue = _parse_boolean(file, row, values["applicable"])
    issued_on, date_issue = _parse_date(file, row, values["issued_on"])
    quantity, quantity_issue = _parse_quantity(file, row, values["quantity"])
    for issue in (applicable_issue, date_issue, quantity_issue):
        if issue is not None:
            issues.append(issue)

    parsed_site = SiteCode(site_code) if site_code is not None else None
    if parsed_site is not None and parsed_site not in known_sites:
        issues.append(_issue(file, row, "site_code", site_code, "등록되지 않은 사업장 코드입니다."))

    permit_type: PermitType | None = None
    if permit_type_value is not None:
        try:
            permit_type = PermitType(permit_type_value)
        except ValueError:
            issues.append(_issue(file, row, "permit_type", permit_type_value, "허용되지 않는 인허가 유형입니다."))

    status: PermitStatus | None = None
    if status_value is not None:
        try:
            status = PermitStatus(status_value)
        except ValueError:
            issues.append(_issue(file, row, "status", status_value, "허용되지 않는 상태값입니다."))

    if issues or parsed_site is None or permit_type is None or applicable is None or status is None:
        return _RowResult(None, tuple(issues))
    return _RowResult(
        PermitUpdate(
            site_code=parsed_site,
            permit_type=permit_type,
            applicable=applicable,
            grade=values["grade"],
            detail=values["detail"],
            items=tuple(item.strip() for item in (values["items"] or "").split("|") if item.strip()),
            quantity=quantity,
            permit_no=values["permit_no"],
            authority=values["authority"],
            issued_on=issued_on,
            conditions=values["conditions"],
            status=status,
        ),
        (),
    )


def _business_key(raw: dict[str, str | None]) -> tuple[str, str] | None:
    values = _normalized(raw)
    site_code = values["site_code"]
    permit_type = values["permit_type"]
    if site_code is None or permit_type is None:
        return None
    return site_code, permit_type


def validate_permit_updates_bytes(
    source_name: str,
    source_bytes: bytes,
    known_sites: frozenset[SiteCode],
) -> ImportPlan:
    """Validate one immutable CSV byte snapshot without database or file writes."""
    try:
        text = source_bytes.decode("utf-8-sig")
        reader = csv.DictReader(io.StringIO(text, newline=""), strict=True)
        headers = tuple(reader.fieldnames or ())
        if headers != REQUIRED_HEADERS:
            return ImportPlan(
                (),
                (
                    ImportIssue(
                        source_name,
                        0,
                        "헤더",
                        ",".join(headers),
                        "템플릿과 정확히 일치하는 헤더가 필요합니다.",
                    ),
                ),
            )
        rows = tuple(enumerate(reader, start=1))
    except (UnicodeDecodeError, csv.Error):
        return ImportPlan((), (ImportIssue(source_name, 0, "CSV", None, "CSV 형식이 올바르지 않습니다."),))

    updates: list[PermitUpdate] = []
    issues: list[ImportIssue] = []
    seen: set[tuple[str, str]] = set()
    for row, values in rows:
        raw = {header: values[header] for header in REQUIRED_HEADERS}
        key = _business_key(raw)
        if key is not None:
            if key in seen:
                issues.append(
                    ImportIssue(
                        source_name,
                        row,
                        "사업장 코드, 인허가 유형",
                        ",".join(key),
                        "파일 안에서 중복된 인허가 업무 키입니다.",
                    )
                )
            seen.add(key)
        extra_cells = values.get(None)
        if extra_cells is not None:
            issues.append(
                ImportIssue(
                    source_name,
                    row,
                    "추가 열",
                    ",".join(extra_cells),
                    "헤더보다 많은 값이 입력되었습니다.",
                )
            )
        result = _parse_row(source_name, row, raw, known_sites)
        issues.extend(result.issues)
        if result.update is None:
            continue
        updates.append(result.update)
    if issues:
        return ImportPlan((), tuple(issues))
    return ImportPlan(tuple(updates), ())


def read_permit_import_snapshot(path: Path, known_sites: frozenset[SiteCode]) -> PermitImportSnapshot:
    """Read once and bind validation results to the same immutable bytes."""
    try:
        source_bytes = path.read_bytes()
    except FileNotFoundError:
        plan = ImportPlan((), (ImportIssue(path.name, 0, "파일", None, "파일을 찾을 수 없습니다."),))
        return PermitImportSnapshot(path.name, b"", plan)
    plan = validate_permit_updates_bytes(path.name, source_bytes, known_sites)
    return PermitImportSnapshot(path.name, source_bytes, plan)


def validate_permit_updates(path: Path, known_sites: frozenset[SiteCode]) -> ImportPlan:
    """Preserve the public path API by delegating to one immutable byte snapshot."""
    return read_permit_import_snapshot(path, known_sites).plan
