def _issue(file: str, row: int, field: str, value: str | None, reason: str) -> ImportIssue:
    """Build a consistently labelled operator-facing issue."""
    return ImportIssue(file, row, _KOREAN_FIELDS[field], value, reason)


def _normalized(values: dict[str, str | None]) -> dict[str, str | None]:
    """Trim CSV text and turn optional blank cells into absent values."""
    return {field: None if value is None or not value.strip() else value.strip() for field, value in values.items()}


def _required_issues(file: str, row: int, raw: dict[str, str | None]) -> tuple[ImportIssue, ...]:
    """Keep empty and whitespace-only required values distinct for operators."""
    issues: list[ImportIssue] = []
    for field in _REQUIRED_FIELDS:
        value = raw[field]
        if value is None:
            issues.append(_issue(file, row, field, value, "필수 열 값이 없습니다."))
        elif value == "":
            issues.append(_issue(file, row, field, value, "필수값이 비어 있습니다."))
        elif not value.strip():
            issues.append(_issue(file, row, field, value, "필수값에 공백만 입력되었습니다."))
    return tuple(issues)


def _parse_date(file: str, row: int, value: str | None) -> tuple[date | None, ImportIssue | None]:
    """Accept only calendar dates written exactly as YYYY-MM-DD."""
    if value is None:
        return None, None
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value) is None:
        return None, _issue(file, row, "issued_on", value, "YYYY-MM-DD 형식의 유효한 날짜가 아닙니다.")
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        return None, _issue(file, row, "issued_on", value, "YYYY-MM-DD 형식의 유효한 날짜가 아닙니다.")
    return parsed, None


